for a0 in 0..2:
    for a1 in 0..64:
        for a2 in 0..64:
            for a3 in 0..128:
                in0 = load w[a0 + 2 * a3, a2]
                in1 = load x[a1, a3]
                f32 v0 = multiply(in0, in1)
                acc0 <- add(acc0, v0) over a3
            o[a1, 64 * a0 + a2] = acc0
